# Collect all unique song IDs
unique_songs = set()

# Add songs from liked songs
for song in liked_songs:
    unique_songs.add(song['song_id'])

# Add songs from liked albums
for album in liked_albums:
    for song_id in album['song_ids']:
        unique_songs.add(song_id)

# Add songs from playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        unique_songs.add(song_id)

print(f"Total unique songs: {len(unique_songs)}")
print(f"Unique song IDs: {sorted(unique_songs)}")

