action.code:
# No requests are 40+ days old. Let me check which ones are pending and how many days
pending_requests = []

for req in sent_requests:
    # Check if not approved and not denied
    if req['approved_at'] is None and req['denied_at'] is None:
        created_date = datetime.fromisoformat(req['created_at'])
        days_since_creation = (current_date - created_date).days

        pending_requests.append({
            'payment_request_id': req['payment_request_id'],
            'receiver_name': req['receiver']['name'],
            'days_pending': days_since_creation,
            'created_at': req['created_at']
        })

print("All pending payment requests:")
for req in pending_requests:
    print(req)

