action.code:
from datetime import datetime, timedelta

current_time = datetime.fromisoformat('2023-05-18T11:58:00')
thirty_days_ago = current_time - timedelta(days=30)

# Filter for payment requests that haven't been approved or denied for 30+ days
pending_old_requests = []
for req in sent_requests:
    if req['approved_at'] is None and req['denied_at'] is None:
        created_at = datetime.fromisoformat(req['created_at'])
        if created_at <= thirty_days_ago:
            pending_old_requests.append(req)

print(f"Requests pending for 30+ days:")
for req in pending_old_requests:
    print(f"  ID: {req['payment_request_id']}, {req['receiver']['name']}, {req['description']}, created: {req['created_at']}")

