# Current date is 2023-05-18, so yesterday is 2023-05-17
# Let me search for transactions from that date across multiple pages
all_transactions = []
for page in range(0, 10):
    trans = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not trans:
        break
    all_transactions.extend(trans)
    # Check if we found any from 2023-05-17
    for t in trans:
        if '2023-05-17' in t['created_at']:
