action.code:
contacts = apis.supervisor.show_contacts()
message = "Get on venmo please!"

# Filter for siblings and roommates without venmo accounts
recipients = []
for contact in contacts:
    if contact.get('relationship') in ['sibling', 'roommate']:
        if not contact.get('has_venmo_account', False):
            recipients.append(contact)

print("Recipients:", recipients)

# Send message to each recipient
for recipient in recipients:
    result = apis.sms.send_sms(
        phone_number=recipient['phone_number'],
        message=message
    )
    print(f"Sent to {recipient['name']}: {result}")

