action.code:
# Get all liked songs with genre info
liked_songs = apis.spotify.show_liked_songs(access_token=token)
songs_with_genre = []

for song in liked_songs:
    song_details = apis.spotify.show_song(access_token=token, song_id=song['song_id'])
    songs_with_genre.append({
        'title': song['title'],
        'genres': song_details.get('genres', []),
        'play_count': song_details.get('play_count', 0)
    })

print("Liked songs with genres:")
for s in songs_with_genre:
    print(f"  {s['title']}: {s['genres']}, plays: {s['play_count']}")

